"use client";

import { useRouter } from "next/navigation";
import { LanguageSwitcher as Switcher, useLanguage as useBaseLanguage } from "localize-dev/react";
import { fallbackLng, supported } from "./i18n.resources";
import type { LanguageSwitcherProps, UseLanguageOptions } from "localize-dev/react";

export { getLanguageInfo } from "localize-dev/react";
export type { LanguageInfo, LanguageSwitcherProps, LanguageState } from "localize-dev/react";

/**
 * Generated by localize.dev. <LanguageSwitcher /> and useLanguage() come from localize-dev/react;
 * this file sets the defaults for this app. Customise where you render it, e.g.
 *   <LanguageSwitcher nameStyle="native-english" languages={["en", "es"]} buttonClassName="…" />
 * useLanguage() gives the current language, its flag and name, the list, and setLanguage().
 * Options: https://uselocalize.dev/docs#switcher
 */

/** On a page with a language in its URL (/es/about), the same page in the new one; else a refresh. */
function follow(router: ReturnType<typeof useRouter>, lng: string) {
  const [, first, ...rest] = window.location.pathname.split("/");
  if (!first || !supported.includes(first)) return router.refresh();
  const bare = `/${rest.join("/")}`;
  router.push(lng === fallbackLng ? bare : `/${lng}${bare === "/" ? "" : bare}`);
}

/** Saves the choice in the "lang" cookie the server reads, then refreshes so server components follow. */
export function LanguageSwitcher(props: LanguageSwitcherProps) {
  const router = useRouter();
  return (
    <Switcher
      persist="cookie"
      {...props}
      onChange={(lng) => {
        props.onChange?.(lng);
        follow(router, lng);
      }}
    />
  );
}

export function useLanguage(options: UseLanguageOptions = {}) {
  const router = useRouter();
  return useBaseLanguage({
    persist: "cookie",
    ...options,
    onChange: (lng) => {
      options.onChange?.(lng);
      follow(router, lng);
    },
  });
}
